WITH remaining_keys AS (SELECT channel FROM orders INTERSECT SELECT channel FROM orders WHERE customer_id = 21), reconciled AS (SELECT s.* FROM orders s JOIN remaining_keys k ON s.channel = k.channel) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, CASE WHEN discount >= 0.44 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_tier, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles, SIZE(COLLECT_SET(status)) AS num_status, SIZE(COLLECT_SET(channel)) AS num_channels, COUNT(DISTINCT customer_id) AS distinct_customer_ids, COUNT(DISTINCT channel) AS distinct_channels, PERCENTILE_APPROX(amount, 0.95) AS amount_p95 FROM reconciled GROUP BY DATE_TRUNC('MONTH', order_date), CASE WHEN discount >= 0.44 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY activity_month DESC
